-- name: Ragdoll
-- description: Ragdoll mod\nMade by Cooliokid 956\n\nUse /ragdoll-bind then press a button to bind to\n\nPress the ragdoll button in the air to ragdoll, hold the button to bounce off the floor\n\n/fling B)

local function vec3f() return {x=0,y=0,z=0} end
local function pt(m) return gPlayerSyncTable[m.playerIndex] end

local function vec3f_mario_ceil(pos, height)
	if gLevelValues.fixCollisionBugs then
        local height = math.max(height + 80, pos.y - 2)
        return find_ceil_height(pos.x, height, pos.z)
    else
        return find_ceil_height(pos.x, height + 80, pos.z)
	end
end

local bind = tonumber(mod_storage_load("bind")) or 0
local isBinding

gPlayerSyncTable[0].friction = 0.988
gPlayerSyncTable[0].restitution = 0.65

_G.ACT_RAGDOLL = allocate_mario_action(ACT_GROUP_AIRBORNE|ACT_FLAG_AIR)
---@param m MarioState
function act_ragdoll(m)
	if m.playerIndex == 0 then m.actionArg = m.controller.buttonDown & bind end
	local bounceSurf = {}
	
	-- when collided with floor
	-- if m.floor.normal.y > 0.29237169 and m.actionArg == 0 then
	-- 	m.faceAngle.y = atan2s(m.vel.z, m.vel.x)
	-- 	m.forwardVel = math.abs(m.forwardVel)
	-- 	return set_mario_action(m, ACT_FORWARD_GROUND_KB, 0)
	-- end
	if m.controller.buttonPressed & A_BUTTON == 0 then return end
	djui_chat_message_create("-------------start-----------")
	local stepProgress = 1

	while stepProgress > 0 do
		djui_chat_message_create("step")

		local mOffset = vec3f()
		vec3f_set(mOffset, m.pos.x, m.pos.y+m.marioObj.hitboxHeight, m.pos.z)

		local lo = collision_find_surface_on_ray(m.pos.x, m.pos.y, m.pos.z, m.vel.x*stepProgress, m.vel.y*stepProgress, m.vel.z*stepProgress)
		if lo and lo.surface then
			djui_chat_message_create("!!!!!!!lo hit!!!!!!!")
			if lo.surface.normal.y > 0.29237169 and m.actionArg == 0 then
				m.faceAngle.y = atan2s(m.vel.z, m.vel.x)
				m.forwardVel = math.abs(m.forwardVel)
				return set_mario_action(m, ACT_FORWARD_GROUND_KB, 0)
			end
			table.insert(bounceSurf, lo.surface)
		end
		local hi = collision_find_surface_on_ray(m.pos.x, mOffset.y, m.pos.z, m.vel.x*stepProgress, m.vel.y*stepProgress, m.vel.z*stepProgress)
		if hi and hi.surface then
			djui_chat_message_create("!!!!!!!hi hit!!!!!!!")
			table.insert(bounceSurf, hi.surface)
		end
		
		local progress = #bounceSurf > 0 and math.min(vec3f_dist(m.pos, lo.hitPos)/vec3f_length(m.vel), vec3f_dist(mOffset, hi.hitPos)/vec3f_length(m.vel), 1) or 1
		-- local progress = lo.surface and vec3f_dist(m.pos, lo.hitPos)
		djui_chat_message_create("ray dist "..vec3f_dist(m.pos, lo.hitPos))
		djui_chat_message_create("vel dist "..vec3f_length(m.vel))
		stepProgress = stepProgress - progress
		djui_chat_message_create("progress is "..progress)
		djui_chat_message_create("step progress is now "..stepProgress)
		local vel = vec3f()
		vec3f_copy(vel, m.vel)
		vec3f_mul(vel, progress/1)
		vec3f_add(m.pos, vel)
		if progress ~= 1 and lo.surface then
			m.pos.y = lo.hitPos.y
		end
		obj_set_gfx_pos_from_pos(m.marioObj)

		if #bounceSurf > 0 then
			local normal = vec3f()
			for i = 1, #bounceSurf do
				vec3f_add(normal, bounceSurf[i].normal)
			end
			vec3f_normalize(normal)
			
			-- split velocity into parallel/perp to normal
			local perp = vec3f_project(m.vel, normal)
			local parallel = { x = m.vel.x - perp.x, y = m.vel.y - perp.y, z = m.vel.z - perp.z }
			
			-- apply friction and restitution
			vec3f_mul(parallel, pt(m).friction)
			vec3f_mul(perp, pt(m).restitution)
			
			-- stop ball in parallel axis
			local parallelLength = vec3f_length(parallel)
			if parallelLength < 0.3 then
				vec3f_mul(parallel, 0)
			end
			
			-- stop ball in perpendicular axis
			local perpLength = vec3f_length(perp)
			if perpLength < 15 then
				vec3f_mul(perp, 0)
			end
			
			-- reflect velocity along normal
			local reflect = {
				x = parallel.x - perp.x,
				y = parallel.y - perp.y,
				z = parallel.z - perp.z
			}
			vec3f_copy(m.vel, reflect)
			
			if vec3f_length(perp) > 5 then cur_obj_play_sound_1(SOUND_ACTION_HIT) end
		else break end
	end

    set_character_animation(m, CHAR_ANIM_AIRBORNE_ON_STOMACH)
	m.marioBodyState.eyeState = MARIO_EYES_DEAD

	vec3s_set(m.angleVel, 2000, 1000, 400)
	vec3s_add(m.faceAngle, m.angleVel)
	vec3s_copy(m.marioObj.header.gfx.angle, m.faceAngle)

	-- gravity
	m.vel.y = m.vel.y - 4
	if m.flags & MARIO_WING_CAP ~= 0 and m.vel.y < 0 and m.input & INPUT_A_DOWN ~= 0 then
		m.marioBodyState.wingFlutter = 1
		m.vel.y = m.vel.y * .9
	end
end
hook_mario_action(ACT_RAGDOLL, act_ragdoll)

---@param m MarioState
---@param o Object
hook_event(HOOK_ON_INTERACT, function (m, o)
	if m.action == ACT_RAGDOLL and m.hurtCounter > 0 then
		m.invincTimer = 2
	end
end)

local replaceActions = {
	[ACT_RAGDOLL] = 1,
	[ACT_FREEFALL] = 1,
	[ACT_FORWARD_AIR_KB] = 1,
	[ACT_BACKWARD_AIR_KB] = 1,
	[ACT_HARD_FORWARD_AIR_KB] = 1,
	[ACT_HARD_BACKWARD_AIR_KB] = 1,
	[ACT_SOFT_BONK] = 1
}
hook_event(HOOK_BEFORE_SET_MARIO_ACTION, function (m, action)
	if replaceActions[action] then
		if action ~= ACT_FREEFALL and action ~= ACT_RAGDOLL then cur_obj_play_sound_1(SOUND_ACTION_HIT) end
		m.faceAngle.x = calculate_pitch(m.marioBodyState.torsoPos, m.marioBodyState.headPos)-32768
		m.faceAngle.z = 0
		return ACT_RAGDOLL
	end
end)

hook_chat_command("fling", "yourself", function ()
	local m = gMarioStates[0]

    m.faceAngle.y = math.random(65536)
    mario_set_forward_vel(m, math.random(30, 200))
	m.vel.y = math.random(30, 150)
	set_mario_action(m, ACT_RAGDOLL, 0)

	return true
end)

hook_chat_command("ragdoll-bind", "to set the ragdoll button", function (msg)
	isBinding = true
	djui_chat_message_create("Press a button to set ragdoll bind.")
	play_sound(SOUND_MENU_EXIT_A_SIGN, vec3f())

	return true
end)

local bindNotice
---@param m MarioState
hook_event(HOOK_MARIO_UPDATE, function (m)
	if m.playerIndex ~= 0 then return end
	if bind == 0 and not bindNotice then djui_chat_message_create("No ragdoll bind set!\nSet one with /ragdoll-bind") bindNotice = 1 end

	if isBinding then
		bind = m.controller.buttonPressed
		if bind ~= 0 then
			mod_storage_save("bind", ""..bind)
			djui_chat_message_create("Ragdoll bind set!")
			play_sound(SOUND_MENU_STAR_SOUND, vec3f())
			isBinding = nil
		end
	end

	if m.controller.buttonPressed & bind ~= 0 and m.action & ACT_FLAG_AIR ~= 0 and m.action ~= ACT_RAGDOLL then
		set_mario_action(m, ACT_RAGDOLL, 0)
	end
end)

